/** Money is always integer cents. */
export type Cents = number;

export function toCents(amount: number): Cents {
  return Math.round(amount * 100);
}

/** Round half away from zero to whole cents. */
export function roundCents(value: number): Cents {
  return Math.sign(value) * Math.round(Math.abs(value));
}

export function formatMoney(cents: Cents, currency = "USD"): string {
  return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(cents / 100);
}

/** Stock levels per SKU. Reservations are all-or-nothing. */
export class InventoryStore {
  private stock = new Map<string, number>();

  constructor(initial: Record<string, number> = {}) {
    for (const [sku, qty] of Object.entries(initial)) this.stock.set(sku, qty);
  }

  available(sku: string): number {
    return this.stock.get(sku) ?? 0;
  }

  set(sku: string, qty: number) {
    this.stock.set(sku, qty);
  }
}

export class OutOfStockError extends Error {
  constructor(readonly sku: string, readonly requested: number, readonly available: number) {
    super(`not enough stock for ${sku}: requested ${requested}, available ${available}`);
  }
}

export function reserveStock(store: InventoryStore, items: { sku: string; quantity: number }[]) {
  const wanted = new Map<string, number>();
  for (const item of items) wanted.set(item.sku, (wanted.get(item.sku) ?? 0) + item.quantity);
  for (const [sku, qty] of wanted) {
    if (store.available(sku) < qty) throw new OutOfStockError(sku, qty, store.available(sku));
  }
  for (const [sku, qty] of wanted) store.set(sku, store.available(sku) - qty);
}

export function releaseStock(store: InventoryStore, items: { sku: string; quantity: number }[]) {
  for (const item of items) store.set(item.sku, store.available(item.sku) + item.quantity);
}

import type { Cents } from "../lib/money";
import type { Customer } from "./types";

/** One point per whole dollar spent; gold members earn double. */
export function loyaltyPointsFor(customer: Customer, total: Cents): number {
  const base = Math.floor(total / 100);
  return customer.loyaltyTier === "gold" ? base * 2 : base;
}

import type { Cents } from "../lib/money";
import type { Coupon, QuoteLine, Region } from "../pricing/quote";

export type Customer = { id: string; email: string; name: string; region: Region; loyaltyTier: "standard" | "gold" };

export type OrderStatus = "paid" | "cancelled";

export type Order = {
  id: string;
  customerId: string;
  lines: QuoteLine[];
  total: Cents;
  chargeId: string;
  status: OrderStatus;
  loyaltyPoints: number;
  createdAt: Date;
};

export type PlaceOrderInput = { customer: Customer; lines: QuoteLine[]; coupon?: Coupon; paymentToken: string };

import { formatMoney } from "../lib/money";
import type { Mailer } from "../notifications/mailer";
import { type PaymentGateway, PaymentError } from "../payments/gateway";
import { buildQuote } from "../pricing/quote";
import { type InventoryStore, releaseStock, reserveStock } from "./inventory";
import { loyaltyPointsFor } from "./loyalty";
import type { Order, PlaceOrderInput } from "./types";

export class OrderNotFoundError extends Error {}

export class OrderService {
  private orders = new Map<string, Order>();
  private seq = 0;

  constructor(
    private inventory: InventoryStore,
    private payments: PaymentGateway,
    private mailer: Mailer,
    private now: () => Date = () => new Date(),
  ) {}

  get(orderId: string): Order | undefined {
    return this.orders.get(orderId);
  }

  async placeOrder(input: PlaceOrderInput): Promise<Order> {
    const quote = buildQuote(input.lines, input.customer.region, input.coupon);
    reserveStock(this.inventory, input.lines);

    const orderId = `ord_${++this.seq}`;
    let charge;
    try {
      charge = await this.payments.charge(input.paymentToken, quote.total, orderId);
    } catch (err) {
      releaseStock(this.inventory, input.lines);
      throw err;
    }
    if (charge.status !== "succeeded") {
      releaseStock(this.inventory, input.lines);
      throw new PaymentError("card declined", charge.declineCode);
    }

    const order: Order = {
      id: orderId,
      customerId: input.customer.id,
      lines: input.lines,
      total: quote.total,
      chargeId: charge.id,
      status: "paid",
      loyaltyPoints: loyaltyPointsFor(input.customer, quote.total),
      createdAt: this.now(),
    };
    this.orders.set(order.id, order);

    // A failed confirmation email must not fail a paid order.
    await this.mailer
      .send(input.customer.email, "order-confirmation", { orderId: order.id, total: formatMoney(order.total), points: order.loyaltyPoints })
      .catch(() => undefined);
    return order;
  }

  async cancelOrder(orderId: string): Promise<Order> {
    const order = this.orders.get(orderId);
    if (!order) throw new OrderNotFoundError(orderId);
    if (order.status === "cancelled") return order;
    const ageMs = this.now().getTime() - order.createdAt.getTime();
    if (ageMs > 24 * 60 * 60 * 1000) throw new Error("orders can only be cancelled within 24 hours");

    await this.payments.refund(order.chargeId);
    releaseStock(this.inventory, order.lines);
    const cancelled: Order = { ...order, status: "cancelled", loyaltyPoints: 0 };
    this.orders.set(orderId, cancelled);
    return cancelled;
  }
}

import { type Cents, roundCents } from "../lib/money";

export type Region = "US-CA" | "US-NY" | "US-OR" | "EU-DE" | "EU-FR";

export type QuoteLine = { sku: string; unitPrice: Cents; quantity: number; taxExempt?: boolean };

export type Coupon =
  | { code: string; kind: "percent"; percent: number; minSubtotal?: Cents }
  | { code: string; kind: "fixed"; amount: Cents; minSubtotal?: Cents }
  | { code: string; kind: "free-shipping" };

export type Quote = {
  lines: { sku: string; quantity: number; unitPrice: Cents; lineTotal: Cents; volumeDiscount: Cents }[];
  subtotal: Cents;
  couponDiscount: Cents;
  shipping: Cents;
  tax: Cents;
  total: Cents;
  appliedCoupon: string | null;
};

export const TAX_RATES: Record<Region, number> = {
  "US-CA": 0.0725,
  "US-NY": 0.04,
  "US-OR": 0,
  "EU-DE": 0.19,
  "EU-FR": 0.2,
};

/** Per-line volume discount: 10+ units 5% off, 50+ units 10% off, 100+ units 15% off. */
export function volumeDiscountRate(quantity: number): number {
  if (quantity >= 100) return 0.15;
  if (quantity >= 50) return 0.1;
  if (quantity >= 10) return 0.05;
  return 0;
}

export const FREE_SHIPPING_THRESHOLD: Cents = 7500;
export const FLAT_SHIPPING: Cents = 695;

export class QuoteError extends Error {}

export function buildQuote(lines: QuoteLine[], region: Region, coupon?: Coupon): Quote {
  if (lines.length === 0) throw new QuoteError("cart is empty");
  for (const line of lines) {
    if (!Number.isInteger(line.quantity) || line.quantity <= 0) throw new QuoteError(`invalid quantity for ${line.sku}`);
    if (line.unitPrice < 0) throw new QuoteError(`invalid price for ${line.sku}`);
  }

  const priced = lines.map((line) => {
    const gross = line.unitPrice * line.quantity;
    const volumeDiscount = roundCents(gross * volumeDiscountRate(line.quantity));
    return { ...line, lineTotal: gross - volumeDiscount, volumeDiscount };
  });
  const subtotal = priced.reduce((sum, l) => sum + l.lineTotal, 0);

  let couponDiscount = 0;
  let appliedCoupon: string | null = null;
  let freeShipping = subtotal >= FREE_SHIPPING_THRESHOLD;
  if (coupon) {
    const min = "minSubtotal" in coupon ? (coupon.minSubtotal ?? 0) : 0;
    if (subtotal >= min) {
      appliedCoupon = coupon.code;
      if (coupon.kind === "percent") couponDiscount = roundCents(subtotal * (coupon.percent / 100));
      else if (coupon.kind === "fixed") couponDiscount = Math.min(coupon.amount, subtotal);
      else freeShipping = true;
    }
  }

  // The coupon discount is spread over taxable lines in proportion to their totals.
  const taxable = priced.filter((l) => !l.taxExempt).reduce((sum, l) => sum + l.lineTotal, 0);
  const taxableAfterCoupon = subtotal === 0 ? 0 : taxable - roundCents(couponDiscount * (taxable / subtotal));
  const tax = roundCents(taxableAfterCoupon * TAX_RATES[region]);
  const shipping = freeShipping ? 0 : FLAT_SHIPPING;

  return {
    lines: priced.map(({ sku, quantity, unitPrice, lineTotal, volumeDiscount }) => ({ sku, quantity, unitPrice, lineTotal, volumeDiscount })),
    subtotal,
    couponDiscount,
    shipping,
    tax,
    total: subtotal - couponDiscount + shipping + tax,
    appliedCoupon,
  };
}

/** Client for the Postbox transactional email API. */
export class Mailer {
  constructor(
    private apiKey: string,
    private baseUrl = "https://api.postbox.example",
    private fetchImpl: typeof fetch = fetch,
  ) {}

  async send(to: string, template: string, data: Record<string, unknown>): Promise<void> {
    const res = await this.fetchImpl(`${this.baseUrl}/messages`, {
      method: "POST",
      headers: { Authorization: `Bearer ${this.apiKey}`, "Content-Type": "application/json" },
      body: JSON.stringify({ to, template, data }),
    });
    if (!res.ok) throw new Error(`email failed with HTTP ${res.status}`);
  }
}

import { type Cents, formatMoney } from "../lib/money";

export type InvoiceLine = { description: string; quantity: number; unitPrice: Cents };

export type Invoice = {
  number: string;
  issuedOn: string; // YYYY-MM-DD
  dueInDays: number;
  seller: { name: string; address: string[]; vatId?: string };
  buyer: { name: string; address: string[]; email: string };
  lines: InvoiceLine[];
  taxRate: number; // e.g. 0.2 for 20%
  currency: string;
  notes?: string;
  paid?: boolean;
};

const escape = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

export function dueDate(issuedOn: string, dueInDays: number): string {
  const d = new Date(`${issuedOn}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + dueInDays);
  return d.toISOString().slice(0, 10);
}

export function invoiceTotals(invoice: Invoice) {
  const subtotal = invoice.lines.reduce((sum, l) => sum + l.unitPrice * l.quantity, 0);
  const tax = Math.round(subtotal * invoice.taxRate);
  return { subtotal, tax, total: subtotal + tax };
}

/** Renders the invoice as a standalone HTML document. */
export function renderInvoice(invoice: Invoice): string {
  if (invoice.lines.length === 0) throw new Error("invoice has no lines");
  const money = (c: Cents) => formatMoney(c, invoice.currency);
  const { subtotal, tax, total } = invoiceTotals(invoice);
  const address = (lines: string[]) => lines.map((l) => `<div>${escape(l)}</div>`).join("");
  const rows = invoice.lines
    .map(
      (l) =>
        `<tr><td>${escape(l.description)}</td><td class="num">${l.quantity}</td><td class="num">${money(l.unitPrice)}</td><td class="num">${money(l.unitPrice * l.quantity)}</td></tr>`,
    )
    .join("\n      ");
  return `<!doctype html>
<html>
<head><meta charset="utf-8"><title>Invoice ${escape(invoice.number)}</title></head>
<body>
  <header>
    <h1>Invoice ${escape(invoice.number)}</h1>
    ${invoice.paid ? '<p class="stamp">PAID</p>' : `<p class="due">Due ${dueDate(invoice.issuedOn, invoice.dueInDays)}</p>`}
  </header>
  <section class="parties">
    <div class="seller"><strong>${escape(invoice.seller.name)}</strong>${address(invoice.seller.address)}${invoice.seller.vatId ? `<div>VAT ${escape(invoice.seller.vatId)}</div>` : ""}</div>
    <div class="buyer"><strong>${escape(invoice.buyer.name)}</strong>${address(invoice.buyer.address)}<div>${escape(invoice.buyer.email)}</div></div>
  </section>
  <table>
    <thead><tr><th>Item</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead>
    <tbody>
      ${rows}
    </tbody>
    <tfoot>
      <tr><td colspan="3">Subtotal</td><td class="num">${money(subtotal)}</td></tr>
      <tr><td colspan="3">Tax (${(invoice.taxRate * 100).toFixed(1)}%)</td><td class="num">${money(tax)}</td></tr>
      <tr class="total"><td colspan="3">Total</td><td class="num">${money(total)}</td></tr>
    </tfoot>
  </table>
  ${invoice.notes ? `<footer><p>${escape(invoice.notes)}</p></footer>` : ""}
</body>
</html>
`;
}

import { describe, expect, it } from "vitest";
import { dueDate, type Invoice, invoiceTotals, renderInvoice } from "./invoice";

function baseInvoice(overrides: Partial<Invoice> = {}): Invoice {
  return {
    number: "INV-001",
    issuedOn: "2024-01-01",
    dueInDays: 14,
    seller: { name: "Acme Ltd", address: ["1 Main St", "Springfield"] },
    buyer: { name: "Bob Buyer", address: ["2 Oak Ave"], email: "bob@example.com" },
    lines: [{ description: "Widget", quantity: 2, unitPrice: 1000 }],
    taxRate: 0.2,
    currency: "USD",
    ...overrides,
  };
}

describe("dueDate", () => {
  it("adds dueInDays to issuedOn", () => {
    expect(dueDate("2024-01-01", 14)).toBe("2024-01-15");
  });

  it("rolls over month and year boundaries", () => {
    expect(dueDate("2024-12-25", 10)).toBe("2025-01-04");
  });
});

describe("invoiceTotals", () => {
  it("sums line items and applies tax rate", () => {
    const invoice = baseInvoice({
      lines: [
        { description: "Widget", quantity: 2, unitPrice: 1000 },
        { description: "Gadget", quantity: 1, unitPrice: 500 },
      ],
      taxRate: 0.2,
    });
    expect(invoiceTotals(invoice)).toEqual({ subtotal: 2500, tax: 500, total: 3000 });
  });

  it("rounds tax to the nearest cent", () => {
    const invoice = baseInvoice({
      lines: [{ description: "Widget", quantity: 1, unitPrice: 333 }],
      taxRate: 0.2,
    });
    expect(invoiceTotals(invoice)).toEqual({ subtotal: 333, tax: 67, total: 400 });
  });
});

describe("renderInvoice", () => {
  it("throws when the invoice has no lines", () => {
    expect(() => renderInvoice(baseInvoice({ lines: [] }))).toThrow("invoice has no lines");
  });

  it("shows a due date and no paid stamp for unpaid invoices", () => {
    const html = renderInvoice(baseInvoice({ paid: false }));
    expect(html).toContain('<p class="due">Due 2024-01-15</p>');
    expect(html).not.toContain('<p class="stamp">PAID</p>');
  });

  it("shows a paid stamp and no due date for paid invoices", () => {
    const html = renderInvoice(baseInvoice({ paid: true }));
    expect(html).toContain('<p class="stamp">PAID</p>');
    expect(html).not.toContain('<p class="due">');
  });

  it("omits the notes footer when there are no notes", () => {
    const html = renderInvoice(baseInvoice());
    expect(html).not.toContain("<footer>");
  });

  it("renders notes when present", () => {
    const html = renderInvoice(baseInvoice({ notes: "Thanks for your business!" }));
    expect(html).toContain("<footer><p>Thanks for your business!</p></footer>");
  });

  it("omits the seller VAT id when not provided", () => {
    const html = renderInvoice(baseInvoice());
    expect(html).not.toContain("VAT");
  });

  it("renders the seller VAT id when provided", () => {
    const html = renderInvoice(
      baseInvoice({ seller: { name: "Acme Ltd", address: ["1 Main St"], vatId: "GB123456789" } }),
    );
    expect(html).toContain("<div>VAT GB123456789</div>");
  });

  it("escapes HTML-sensitive characters in user-controlled fields", () => {
    const html = renderInvoice(
      baseInvoice({
        number: `<script>"&`,
        notes: `<b>bold</b> & "quoted"`,
        seller: { name: `A & B <Co>`, address: [`1 "Main" St`], vatId: `<VAT>&"1"` },
        buyer: { name: `<Buyer>`, address: [`<addr>`], email: `bob"@<example>.com` },
        lines: [{ description: `<Widget> & "Co"`, quantity: 1, unitPrice: 100 }],
      }),
    );
    expect(html).not.toContain("<script>");
    expect(html).toContain("&lt;script&gt;&quot;&amp;");
    expect(html).toContain("A &amp; B &lt;Co&gt;");
    expect(html).toContain("1 &quot;Main&quot; St");
    expect(html).toContain("&lt;VAT&gt;&amp;&quot;1&quot;");
    expect(html).toContain("&lt;Buyer&gt;");
    expect(html).toContain("&lt;addr&gt;");
    expect(html).toContain("bob&quot;@&lt;example&gt;.com");
    expect(html).toContain("&lt;Widget&gt; &amp; &quot;Co&quot;");
    expect(html).toContain("&lt;b&gt;bold&lt;/b&gt; &amp; &quot;quoted&quot;");
  });

  it("renders totals and tax rate in the footer", () => {
    const html = renderInvoice(
      baseInvoice({
        lines: [{ description: "Widget", quantity: 2, unitPrice: 1000 }],
        taxRate: 0.2,
        currency: "USD",
      }),
    );
    expect(html).toContain("Tax (20.0%)");
    expect(html).toContain('<td colspan="3">Subtotal</td><td class="num">$20.00</td>');
    expect(html).toContain('<td colspan="3">Tax (20.0%)</td><td class="num">$4.00</td>');
