class FakePaymentGateway extends PaymentGateway {
  charges: { token: string; amount: Cents; orderId: string }[] = [];
  refunds: string[] = [];
  chargeImpl: (token: string, amount: Cents, orderId: string) => Promise<Charge> = async (_token, amount, orderId) => ({
    id: `ch_${orderId}`,
    status: "succeeded",
    amount,
  });
  refundImpl: (chargeId: string) => Promise<void> = async () => undefined;

  constructor() {
    super("test-key");
  }

  override async charge(token: string, amount: Cents, orderId: string): Promise<Charge> {
