const customer: Customer = {
  id: "cus_1",
  email: "shopper@example.com",
  name: "Shopper",
  region: "US-OR",
  loyaltyTier: "standard",
};

function buildInput(overrides: Partial<PlaceOrderInput> = {}): PlaceOrderInput {
  return {
    customer,
    lines: [{ sku: "WIDGET", unitPrice: 2000, quantity: 1 }],
    paymentToken: "tok_visa",
    ...overrides,
  };
}

// US-OR has 0% tax; a single $20 widget stays below the free-shipping
// threshold, so the expected total is 2000 (subtotal) + 695 (flat shipping).
const EXPECTED_TOTAL = 2695;

describe("OrderService", () => {
  let inventory: InventoryStore;
  let payments: FakePaymentGateway;
  let mailer: FakeMailer;
  let now: Date;
  let service: OrderService;

  beforeEach(() => {
    inventory = new InventoryStore({ WIDGET: 5 });
    payments = new FakePaymentGateway();
    mailer = new FakeMailer();
    now = new Date("2026-01-01T00:00:00.000Z");
    service = new OrderService(inventory, payments, mailer, () => now);
  });

  describe("placeOrder", () => {
    it("reserves stock, charges the quoted total, and returns a paid order", async () => {
      const order = await service.placeOrder(buildInput());

      expect(order.status).toBe("paid");
      expect(order.total).toBe(EXPECTED_TOTAL);
      expect(order.chargeId).toBe(`ch_${order.id}`);
      expect(order.loyaltyPoints).toBe(26);
      expect(inventory.available("WIDGET")).toBe(4);
      expect(payments.charges).toEqual([{ token: "tok_visa", amount: EXPECTED_TOTAL, orderId: order.id }]);
      expect(service.get(order.id)).toEqual(order);
    });

    it("sends a confirmation email with the order details", async () => {
      const order = await service.placeOrder(buildInput());

      expect(mailer.sent).toHaveLength(1);
      expect(mailer.sent[0]).toMatchObject({
        to: customer.email,
        template: "order-confirmation",
        data: { orderId: order.id, points: order.loyaltyPoints },
      });
    });

    it("still returns the paid order when the confirmation email fails", async () => {
      mailer.sendImpl = async () => {
        throw new Error("postbox is down");
      };

      const order = await service.placeOrder(buildInput());

      expect(order.status).toBe("paid");
    });

    it("throws without charging when stock is insufficient", async () => {
      inventory.set("WIDGET", 0);

      await expect(service.placeOrder(buildInput())).rejects.toBeInstanceOf(OutOfStockError);
      expect(payments.charges).toHaveLength(0);
      expect(inventory.available("WIDGET")).toBe(0);
    });

    it("releases stock and rejects when the charge is declined", async () => {
      payments.chargeImpl = async (_token, amount, orderId) => ({
        id: `ch_${orderId}`,
        status: "declined",
        amount,
        declineCode: "insufficient_funds",
      });

      await expect(service.placeOrder(buildInput())).rejects.toThrow(PaymentError);
      expect(inventory.available("WIDGET")).toBe(5);
      expect(mailer.sent).toHaveLength(0);
    });

    it("releases stock and rejects when the payment gateway throws", async () => {
      payments.chargeImpl = async () => {
        throw new PaymentError("charge failed with HTTP 500");
      };

      await expect(service.placeOrder(buildInput())).rejects.toThrow("charge failed with HTTP 500");
      expect(inventory.available("WIDGET")).toBe(5);
      expect(mailer.sent).toHaveLength(0);
    });
  });

  describe("cancelOrder", () => {
    it("refunds the charge, releases stock, and zeroes loyalty points", async () => {
      const order = await service.placeOrder(buildInput());

      const cancelled = await service.cancelOrder(order.id);

      expect(cancelled.status).toBe("cancelled");
      expect(cancelled.loyaltyPoints).toBe(0);
      expect(payments.refunds).toEqual([order.chargeId]);
      expect(inventory.available("WIDGET")).toBe(5);
    });

    it("is idempotent for an already-cancelled order", async () => {
      const order = await service.placeOrder(buildInput());
      await service.cancelOrder(order.id);

      const result = await service.cancelOrder(order.id);

      expect(result.status).toBe("cancelled");
      expect(payments.refunds).toHaveLength(1);
    });

    it("allows cancellation right up to the 24-hour boundary", async () => {
      const order = await service.placeOrder(buildInput());
      now = new Date(order.createdAt.getTime() + 24 * 60 * 60 * 1000);

      const cancelled = await service.cancelOrder(order.id);

      expect(cancelled.status).toBe("cancelled");
    });

    it("rejects cancellation once the 24-hour window has passed", async () => {
      const order = await service.placeOrder(buildInput());
      now = new Date(order.createdAt.getTime() + 24 * 60 * 60 * 1000 + 1);

      await expect(service.cancelOrder(order.id)).rejects.toThrow("orders can only be cancelled within 24 hours");
      expect(payments.refunds).toHaveLength(0);
      expect(inventory.available("WIDGET")).toBe(4);
    });

    it("throws OrderNotFoundError for an unknown order id", async () => {
      await expect(service.cancelOrder("ord_missing")).rejects.toBeInstanceOf(OrderNotFoundError);
    });
  });
});

import type { Cents } from "../lib/money";
import type { Coupon, QuoteLine, Region } from "../pricing/quote";

export type Customer = { id: string; email: string; name: string; region: Region; loyaltyTier: "standard" | "gold" };

export type OrderStatus = "paid" | "cancelled";

export type Order = {
  id: string;
  customerId: string;
  lines: QuoteLine[];
  total: Cents;
  chargeId: string;
  status: OrderStatus;
  loyaltyPoints: number;
  createdAt: Date;
};

export type PlaceOrderInput = { customer: Customer; lines: QuoteLine[]; coupon?: Coupon; paymentToken: string };

import { formatMoney } from "../lib/money";
import type { Mailer } from "../notifications/mailer";
import { type PaymentGateway, PaymentError } from "../payments/gateway";
import { buildQuote } from "../pricing/quote";
import { type InventoryStore, releaseStock, reserveStock } from "./inventory";
import { loyaltyPointsFor } from "./loyalty";
import type { Order, PlaceOrderInput } from "./types";

export class OrderNotFoundError extends Error {}

export class OrderService {
  private orders = new Map<string, Order>();
  private seq = 0;

  constructor(
    private inventory: InventoryStore,
    private payments: PaymentGateway,
    private mailer: Mailer,
    private now: () => Date = () => new Date(),
  ) {}

  get(orderId: string): Order | undefined {
    return this.orders.get(orderId);
  }

  async placeOrder(input: PlaceOrderInput): Promise<Order> {
    const quote = buildQuote(input.lines, input.customer.region, input.coupon);
    reserveStock(this.inventory, input.lines);

    const orderId = `ord_${++this.seq}`;
    let charge;
    try {
      charge = await this.payments.charge(input.paymentToken, quote.total, orderId);
    } catch (err) {
      releaseStock(this.inventory, input.lines);
      throw err;
    }
    if (charge.status !== "succeeded") {
      releaseStock(this.inventory, input.lines);
      throw new PaymentError("card declined", charge.declineCode);
    }

    const order: Order = {
      id: orderId,
      customerId: input.customer.id,
      lines: input.lines,
      total: quote.total,
      chargeId: charge.id,
      status: "paid",
      loyaltyPoints: loyaltyPointsFor(input.customer, quote.total),
      createdAt: this.now(),
    };
    this.orders.set(order.id, order);

    // A failed confirmation email must not fail a paid order.
    await this.mailer
      .send(input.customer.email, "order-confirmation", { orderId: order.id, total: formatMoney(order.total), points: order.loyaltyPoints })
      .catch(() => undefined);
    return order;
  }

  async cancelOrder(orderId: string): Promise<Order> {
    const order = this.orders.get(orderId);
    if (!order) throw new OrderNotFoundError(orderId);
    if (order.status === "cancelled") return order;
    const ageMs = this.now().getTime() - order.createdAt.getTime();
    if (ageMs > 24 * 60 * 60 * 1000) throw new Error("orders can only be cancelled within 24 hours");

    await this.payments.refund(order.chargeId);
    releaseStock(this.inventory, order.lines);
    const cancelled: Order = { ...order, status: "cancelled", loyaltyPoints: 0 };
    this.orders.set(orderId, cancelled);
    return cancelled;
  }
}

import { type Cents, roundCents } from "../lib/money";

export type Region = "US-CA" | "US-NY" | "US-OR" | "EU-DE" | "EU-FR";

export type QuoteLine = { sku: string; unitPrice: Cents; quantity: number; taxExempt?: boolean };

export type Coupon =
