describe("retries", () => {
  const okTracking = () => json({ tracking_number: "SF1", carrier: "shipfast", events: [] } satisfies ApiTrackingResponse);

  it("retries on 429 honouring Retry-After (seconds)", async () => {
    const { client, fetchImpl, sleep } = setup([json({}, 429, { "Retry-After": "3" }), okTracking()]);
    const tracking = await client.track("SF1");
    expect(tracking?.trackingNumber).toBe("SF1");
    expect(fetchImpl).toHaveBeenCalledTimes(2);
    expect(sleep.mock.calls).toEqual([[3000]]);
  });

  it("retries on 5xx with exponential backoff", async () => {
    const { client, fetchImpl, sleep } = setup([json({}, 503), json({}, 500), okTracking()]);
    await client.track("SF1");
    expect(fetchImpl).toHaveBeenCalledTimes(3);
    expect(sleep.mock.calls.map(([ms]) => ms)).toEqual([500, 1000]);
  });

  it("ignores an invalid Retry-After header and falls back to backoff", async () => {
    const { client, sleep } = setup([json({}, 429, { "Retry-After": "soon" }), okTracking()]);
    await client.track("SF1");
    expect(sleep.mock.calls).toEqual([[500]]);
  });

  it("gives up after maxRetries and throws the final error", async () => {
    const { client, fetchImpl, sleep } = setup([
      json({}, 502),
      json({}, 502),
      apiError(502, "bad_gateway", "upstream down"),
    ]);
    await expect(client.track("SF1")).rejects.toMatchObject({ status: 502, code: "bad_gateway", message: "upstream down" });
    expect(fetchImpl).toHaveBeenCalledTimes(3); // 1 attempt + 2 retries
    expect(sleep).toHaveBeenCalledTimes(2);
  });

  it("respects a custom maxRetries of 0", async () => {
    const { client, fetchImpl, sleep } = setup([json({}, 500)], { maxRetries: 0 });
    await expect(client.track("SF1")).rejects.toMatchObject({ status: 500 });
    expect(fetchImpl).toHaveBeenCalledTimes(1);
    expect(sleep).not.toHaveBeenCalled();
  });

  it("does not retry other 4xx errors", async () => {
    const { client, fetchImpl, sleep } = setup([apiError(400, "bad_request", "bad")]);
    await expect(client.track("SF1")).rejects.toMatchObject({ status: 400 });
    expect(fetchImpl).toHaveBeenCalledTimes(1);
    expect(sleep).not.toHaveBeenCalled();
  });
});

describe("API errors", () => {
