import { beforeEach, describe, expect, it, vi } from "vitest";
import { Mailer } from "../notifications/mailer";
import { PaymentError, PaymentGateway } from "../payments/gateway";
import type { QuoteLine } from "../pricing/quote";
import { InventoryStore, OutOfStockError } from "./inventory";
import { OrderNotFoundError, OrderService } from "./service";
import type { Customer } from "./types";

function fakeResponse(body: unknown, ok = true, status = 200): Response {
  return { ok, status, json: async () => body } as unknown as Response;
}

/** Routes charges to `onCharge` and refunds to `onRefund`; both default to a successful charge/refund. */
function makePaymentGateway(
  onCharge: () => Response | Promise<Response> = () => fakeResponse({ id: "ch_default", status: "succeeded", amount: 0 }),
  onRefund: () => Response | Promise<Response> = () => fakeResponse({}),
) {
  const fetchImpl = vi.fn(async (url: string | URL) => (String(url).includes("/refunds") ? onRefund() : onCharge()));
  const gateway = new PaymentGateway("test-key", "https://api.paywise.example/v1", fetchImpl as unknown as typeof fetch);
  return { gateway, fetchImpl };
}

function makeMailer(): Mailer {
  const fetchImpl = (async () => fakeResponse({})) as unknown as typeof fetch;
  return new Mailer("test-key", "https://api.postbox.example", fetchImpl);
}

const customer: Customer = { id: "cus_1", email: "ann@example.com", name: "Ann", region: "US-OR", loyaltyTier: "standard" };
const lines: QuoteLine[] = [{ sku: "sku_1", unitPrice: 1000, quantity: 2 }];

describe("OrderService", () => {
  let inventory: InventoryStore;

  beforeEach(() => {
    inventory = new InventoryStore({ sku_1: 10 });
  });

  it("places an order on successful payment, reserving stock and crediting loyalty points", async () => {
    const { gateway } = makePaymentGateway(() => fakeResponse({ id: "ch_1", status: "succeeded", amount: 2000 }));
    const service = new OrderService(inventory, gateway, makeMailer());

    const order = await service.placeOrder({ customer, lines, paymentToken: "tok_1" });

    expect(order.status).toBe("paid");
    expect(order.chargeId).toBe("ch_1");
    expect(order.total).toBe(2695); // $20 subtotal + $6.95 flat shipping (below free-shipping threshold), 0% tax in US-OR
    expect(order.loyaltyPoints).toBe(26);
    expect(inventory.available("sku_1")).toBe(8);
    expect(service.get(order.id)).toEqual(order);
  });

  it("does not fail the order when the confirmation email fails to send", async () => {
    const { gateway } = makePaymentGateway(() => fakeResponse({ id: "ch_1", status: "succeeded", amount: 2000 }));
    const failingMailer = new Mailer("test-key", "https://api.postbox.example", (async () => fakeResponse({}, false, 500)) as unknown as typeof fetch);
    const service = new OrderService(inventory, gateway, failingMailer);

    const order = await service.placeOrder({ customer, lines, paymentToken: "tok_1" });

    expect(order.status).toBe("paid");
  });

  it("throws OutOfStockError and never contacts the payment gateway when stock is insufficient", async () => {
    inventory.set("sku_1", 1);
    const { gateway, fetchImpl } = makePaymentGateway();
    const service = new OrderService(inventory, gateway, makeMailer());

    await expect(service.placeOrder({ customer, lines, paymentToken: "tok_1" })).rejects.toBeInstanceOf(OutOfStockError);
    expect(fetchImpl).not.toHaveBeenCalled();
    expect(inventory.available("sku_1")).toBe(1);
  });

  it("releases reserved stock and throws PaymentError when the charge is declined", async () => {
    const { gateway } = makePaymentGateway(() => fakeResponse({ id: "ch_2", status: "declined", decline_code: "insufficient_funds" }));
    const service = new OrderService(inventory, gateway, makeMailer());

    await expect(service.placeOrder({ customer, lines, paymentToken: "tok_1" })).rejects.toMatchObject({
      declineCode: "insufficient_funds",
    });
    expect(inventory.available("sku_1")).toBe(10);
  });

  it("releases reserved stock and rethrows when the payment gateway call fails", async () => {
    const { gateway } = makePaymentGateway(() => fakeResponse({}, false, 500));
    const service = new OrderService(inventory, gateway, makeMailer());

    await expect(service.placeOrder({ customer, lines, paymentToken: "tok_1" })).rejects.toBeInstanceOf(PaymentError);
    expect(inventory.available("sku_1")).toBe(10);
  });

  it("cancels a paid order within 24 hours, refunding the charge and restocking", async () => {
    const { gateway, fetchImpl } = makePaymentGateway(() => fakeResponse({ id: "ch_3", status: "succeeded", amount: 2000 }));
    let now = new Date("2026-01-01T00:00:00Z");
    const service = new OrderService(inventory, gateway, makeMailer(), () => now);

    const order = await service.placeOrder({ customer, lines, paymentToken: "tok_1" });
    now = new Date("2026-01-01T10:00:00Z");
    const cancelled = await service.cancelOrder(order.id);

    expect(cancelled.status).toBe("cancelled");
    expect(cancelled.loyaltyPoints).toBe(0);
    expect(inventory.available("sku_1")).toBe(10);
    expect(fetchImpl).toHaveBeenCalledWith(expect.stringContaining("/charges/ch_3/refunds"), expect.anything());
  });

  it("refuses to cancel an order older than 24 hours and leaves stock untouched", async () => {
    const { gateway } = makePaymentGateway(() => fakeResponse({ id: "ch_4", status: "succeeded", amount: 2000 }));
    let now = new Date("2026-01-01T00:00:00Z");
    const service = new OrderService(inventory, gateway, makeMailer(), () => now);

    const order = await service.placeOrder({ customer, lines, paymentToken: "tok_1" });
    now = new Date("2026-01-02T00:00:01Z");

    await expect(service.cancelOrder(order.id)).rejects.toThrow("orders can only be cancelled within 24 hours");
    expect(inventory.available("sku_1")).toBe(8);
  });

  it("returns the already-cancelled order without refunding again", async () => {
    const { gateway, fetchImpl } = makePaymentGateway(() => fakeResponse({ id: "ch_5", status: "succeeded", amount: 2000 }));
    const service = new OrderService(inventory, gateway, makeMailer());

    const order = await service.placeOrder({ customer, lines, paymentToken: "tok_1" });
    const first = await service.cancelOrder(order.id);
    fetchImpl.mockClear();
    const second = await service.cancelOrder(order.id);

    expect(second).toEqual(first);
    expect(fetchImpl).not.toHaveBeenCalled();
  });

  it("throws OrderNotFoundError when cancelling an unknown order", async () => {
    const { gateway } = makePaymentGateway();
    const service = new OrderService(inventory, gateway, makeMailer());

    await expect(service.cancelOrder("does-not-exist")).rejects.toBeInstanceOf(OrderNotFoundError);
  });
});

import type { Cents } from "../lib/money";
import type { Coupon, QuoteLine, Region } from "../pricing/quote";

export type Customer = { id: string; email: string; name: string; region: Region; loyaltyTier: "standard" | "gold" };

export type OrderStatus = "paid" | "cancelled";

export type Order = {
  id: string;
  customerId: string;
  lines: QuoteLine[];
  total: Cents;
  chargeId: string;
  status: OrderStatus;
  loyaltyPoints: number;
  createdAt: Date;
};

export type PlaceOrderInput = { customer: Customer; lines: QuoteLine[]; coupon?: Coupon; paymentToken: string };

import { formatMoney } from "../lib/money";
import type { Mailer } from "../notifications/mailer";
import { type PaymentGateway, PaymentError } from "../payments/gateway";
import { buildQuote } from "../pricing/quote";
import { type InventoryStore, releaseStock, reserveStock } from "./inventory";
import { loyaltyPointsFor } from "./loyalty";
import type { Order, PlaceOrderInput } from "./types";

export class OrderNotFoundError extends Error {}

export class OrderService {
  private orders = new Map<string, Order>();
  private seq = 0;

  constructor(
    private inventory: InventoryStore,
    private payments: PaymentGateway,
    private mailer: Mailer,
    private now: () => Date = () => new Date(),
  ) {}

  get(orderId: string): Order | undefined {
    return this.orders.get(orderId);
  }

  async placeOrder(input: PlaceOrderInput): Promise<Order> {
    const quote = buildQuote(input.lines, input.customer.region, input.coupon);
    reserveStock(this.inventory, input.lines);

    const orderId = `ord_${++this.seq}`;
    let charge;
    try {
      charge = await this.payments.charge(input.paymentToken, quote.total, orderId);
    } catch (err) {
      releaseStock(this.inventory, input.lines);
      throw err;
    }
    if (charge.status !== "succeeded") {
      releaseStock(this.inventory, input.lines);
      throw new PaymentError("card declined", charge.declineCode);
    }

    const order: Order = {
      id: orderId,
      customerId: input.customer.id,
      lines: input.lines,
      total: quote.total,
      chargeId: charge.id,
      status: "paid",
      loyaltyPoints: loyaltyPointsFor(input.customer, quote.total),
      createdAt: this.now(),
    };
    this.orders.set(order.id, order);

    // A failed confirmation email must not fail a paid order.
    await this.mailer
      .send(input.customer.email, "order-confirmation", { orderId: order.id, total: formatMoney(order.total), points: order.loyaltyPoints })
      .catch(() => undefined);
    return order;
  }

  async cancelOrder(orderId: string): Promise<Order> {
    const order = this.orders.get(orderId);
    if (!order) throw new OrderNotFoundError(orderId);
    if (order.status === "cancelled") return order;
    const ageMs = this.now().getTime() - order.createdAt.getTime();
    if (ageMs > 24 * 60 * 60 * 1000) throw new Error("orders can only be cancelled within 24 hours");

    await this.payments.refund(order.chargeId);
    releaseStock(this.inventory, order.lines);
    const cancelled: Order = { ...order, status: "cancelled", loyaltyPoints: 0 };
    this.orders.set(orderId, cancelled);
    return cancelled;
  }
}

import { type Cents, roundCents } from "../lib/money";

export type Region = "US-CA" | "US-NY" | "US-OR" | "EU-DE" | "EU-FR";

export type QuoteLine = { sku: string; unitPrice: Cents; quantity: number; taxExempt?: boolean };

export type Coupon =
  | { code: string; kind: "percent"; percent: number; minSubtotal?: Cents }
  | { code: string; kind: "fixed"; amount: Cents; minSubtotal?: Cents }
  | { code: string; kind: "free-shipping" };

export type Quote = {
  lines: { sku: string; quantity: number; unitPrice: Cents; lineTotal: Cents; volumeDiscount: Cents }[];
  subtotal: Cents;
  couponDiscount: Cents;
  shipping: Cents;
  tax: Cents;
  total: Cents;
  appliedCoupon: string | null;
};

export const TAX_RATES: Record<Region, number> = {
  "US-CA": 0.0725,
  "US-NY": 0.04,
  "US-OR": 0,
  "EU-DE": 0.19,
  "EU-FR": 0.2,
};

/** Per-line volume discount: 10+ units 5% off, 50+ units 10% off, 100+ units 15% off. */
export function volumeDiscountRate(quantity: number): number {
  if (quantity >= 100) return 0.15;
  if (quantity >= 50) return 0.1;
  if (quantity >= 10) return 0.05;
  return 0;
}

export const FREE_SHIPPING_THRESHOLD: Cents = 7500;
export const FLAT_SHIPPING: Cents = 695;

export class QuoteError extends Error {}

export function buildQuote(lines: QuoteLine[], region: Region, coupon?: Coupon): Quote {
  if (lines.length === 0) throw new QuoteError("cart is empty");
  for (const line of lines) {
    if (!Number.isInteger(line.quantity) || line.quantity <= 0) throw new QuoteError(`invalid quantity for ${line.sku}`);
    if (line.unitPrice < 0) throw new QuoteError(`invalid price for ${line.sku}`);
  }

  const priced = lines.map((line) => {
    const gross = line.unitPrice * line.quantity;
    const volumeDiscount = roundCents(gross * volumeDiscountRate(line.quantity));
    return { ...line, lineTotal: gross - volumeDiscount, volumeDiscount };
  });
  const subtotal = priced.reduce((sum, l) => sum + l.lineTotal, 0);

  let couponDiscount = 0;
  let appliedCoupon: string | null = null;
  let freeShipping = subtotal >= FREE_SHIPPING_THRESHOLD;
  if (coupon) {
    const min = "minSubtotal" in coupon ? (coupon.minSubtotal ?? 0) : 0;
    if (subtotal >= min) {
      appliedCoupon = coupon.code;
      if (coupon.kind === "percent") couponDiscount = roundCents(subtotal * (coupon.percent / 100));
      else if (coupon.kind === "fixed") couponDiscount = Math.min(coupon.amount, subtotal);
      else freeShipping = true;
    }
  }

  // The coupon discount is spread over taxable lines in proportion to their totals.
  const taxable = priced.filter((l) => !l.taxExempt).reduce((sum, l) => sum + l.lineTotal, 0);
  const taxableAfterCoupon = subtotal === 0 ? 0 : taxable - roundCents(couponDiscount * (taxable / subtotal));
  const tax = roundCents(taxableAfterCoupon * TAX_RATES[region]);
  const shipping = freeShipping ? 0 : FLAT_SHIPPING;

  return {
    lines: priced.map(({ sku, quantity, unitPrice, lineTotal, volumeDiscount }) => ({ sku, quantity, unitPrice, lineTotal, volumeDiscount })),
    subtotal,
    couponDiscount,
    shipping,
    tax,
    total: subtotal - couponDiscount + shipping + tax,
    appliedCoupon,
  };
}

/** Client for the Postbox transactional email API. */
export class Mailer {
