  async cancelOrder(orderId: string): Promise<Order> {
    const order = this.orders.get(orderId);
    if (!order) throw new OrderNotFoundError(orderId);
    if (order.status === "cancelled") return order;
    const ageMs = this.now().getTime() - order.createdAt.getTime();
    if (ageMs > 24 * 60 * 60 * 1000) throw new Error("orders can only be cancelled within 24 hours");

    await this.payments.refund(order.chargeId);
    releaseStock(this.inventory, order.lines);
    const cancelled: Order = { ...order, status: "cancelled", loyaltyPoints: 0 };
    this.orders.set(orderId, cancelled);
    return cancelled;
  }
}

import { describe, expect, it } from "vitest";
import {
  buildQuote,
  FLAT_SHIPPING,
  FREE_SHIPPING_THRESHOLD,
  QuoteError,
  TAX_RATES,
  volumeDiscountRate,
  type QuoteLine,
} from "./quote";

const line = (unitPrice: number, quantity = 1, extra: Partial<QuoteLine> = {}): QuoteLine => ({
  sku: "SKU",
  unitPrice,
  quantity,
  ...extra,
});

describe("volume discount tiers", () => {
  it.each([
    [1, 0],
    [9, 0],
    [10, 0.05],
    [49, 0.05],
    [50, 0.1],
    [99, 0.1],
    [100, 0.15],
    [500, 0.15],
  ])("quantity %i gets rate %f", (qty, rate) => {
    expect(volumeDiscountRate(qty)).toBe(rate);
  });

  it.each([
    [9, 0, 900],
    [10, 50, 950],
    [50, 500, 4500],
    [100, 1500, 8500],
  ])("applies to the line total for quantity %i", (qty, discount, total) => {
    const q = buildQuote([line(100, qty)], "US-OR");
    expect(q.lines[0]).toMatchObject({ quantity: qty, volumeDiscount: discount, lineTotal: total });
    expect(q.subtotal).toBe(total);
  });

  it("discounts each line independently", () => {
    const q = buildQuote([line(100, 10), line(100, 9)], "US-OR");
    expect(q.lines.map((l) => l.volumeDiscount)).toEqual([50, 0]);
    expect(q.subtotal).toBe(950 + 900);
  });

  it("rounds the discount to whole cents", () => {
    // gross 10 * 5% = 0.5 -> rounds to 1
    const q = buildQuote([line(1, 10)], "US-OR");
    expect(q.lines[0].volumeDiscount).toBe(1);
    expect(q.lines[0].lineTotal).toBe(9);
  });
});

describe("coupons", () => {
  it("returns no discount and null coupon when none is given", () => {
    const q = buildQuote([line(5000)], "US-OR");
    expect(q.couponDiscount).toBe(0);
    expect(q.appliedCoupon).toBeNull();
  });

  it("applies a percent coupon to the subtotal", () => {
    const q = buildQuote([line(5000)], "US-OR", { code: "TEN", kind: "percent", percent: 10 });
    expect(q.couponDiscount).toBe(500);
    expect(q.appliedCoupon).toBe("TEN");
    expect(q.total).toBe(5000 - 500 + FLAT_SHIPPING);
  });

  it("rounds percent discounts to whole cents", () => {
    const q = buildQuote([line(333)], "US-OR", { code: "P", kind: "percent", percent: 10 });
    expect(q.couponDiscount).toBe(33);
  });

  it("applies a fixed coupon", () => {
    const q = buildQuote([line(5000)], "US-OR", { code: "FIVE", kind: "fixed", amount: 500 });
    expect(q.couponDiscount).toBe(500);
    expect(q.total).toBe(5000 - 500 + FLAT_SHIPPING);
  });

  it("caps a fixed coupon at the subtotal", () => {
    const q = buildQuote([line(500)], "US-OR", { code: "BIG", kind: "fixed", amount: 1000 });
    expect(q.couponDiscount).toBe(500);
    expect(q.total).toBe(FLAT_SHIPPING);
  });

  it("free-shipping coupon waives shipping on a small cart", () => {
    const q = buildQuote([line(5000)], "US-OR", { code: "SHIP", kind: "free-shipping" });
    expect(q.shipping).toBe(0);
    expect(q.couponDiscount).toBe(0);
    expect(q.appliedCoupon).toBe("SHIP");
  });

  it("does not apply a coupon below its minimum subtotal", () => {
    const q = buildQuote([line(5000)], "US-OR", { code: "MIN", kind: "percent", percent: 10, minSubtotal: 6000 });
    expect(q.couponDiscount).toBe(0);
    expect(q.appliedCoupon).toBeNull();
  });

  it("applies a coupon exactly at its minimum subtotal", () => {
    const q = buildQuote([line(6000)], "US-OR", { code: "MIN", kind: "fixed", amount: 100, minSubtotal: 6000 });
    expect(q.couponDiscount).toBe(100);
    expect(q.appliedCoupon).toBe("MIN");
  });

  it("checks the minimum against the post-volume-discount subtotal", () => {
    // gross 1000, subtotal 950 after 5% volume discount
    const q = buildQuote([line(100, 10)], "US-OR", { code: "MIN", kind: "fixed", amount: 100, minSubtotal: 1000 });
    expect(q.appliedCoupon).toBeNull();
  });
});

describe("tax", () => {
  it.each(Object.entries(TAX_RATES) as [keyof typeof TAX_RATES, number][])("charges %s at its rate", (region, rate) => {
    const q = buildQuote([line(10000)], region);
    expect(q.tax).toBe(Math.round(10000 * rate));
  });

  it("uses known amounts for specific regions", () => {
    expect(buildQuote([line(10000)], "US-CA").tax).toBe(725);
    expect(buildQuote([line(10000)], "US-NY").tax).toBe(400);
    expect(buildQuote([line(10000)], "US-OR").tax).toBe(0);
    expect(buildQuote([line(10000)], "EU-DE").tax).toBe(1900);
    expect(buildQuote([line(10000)], "EU-FR").tax).toBe(2000);
  });

  it("excludes tax-exempt lines from the taxable base", () => {
    const q = buildQuote([line(10000), line(5000, 1, { taxExempt: true })], "EU-FR");
    expect(q.subtotal).toBe(15000);
    expect(q.tax).toBe(2000);
  });

  it("charges no tax when every line is exempt", () => {
    const q = buildQuote([line(10000, 1, { taxExempt: true })], "EU-DE");
    expect(q.tax).toBe(0);
    expect(q.total).toBe(10000);
  });

  it("spreads the coupon discount over taxable lines proportionally", () => {
    // taxable 6000, exempt 4000, 10% coupon = 1000; taxable share 600 -> 5400 * 4% = 216
    const q = buildQuote([line(6000), line(4000, 1, { taxExempt: true })], "US-NY", {
      code: "TEN",
      kind: "percent",
      percent: 10,
    });
    expect(q.couponDiscount).toBe(1000);
    expect(q.tax).toBe(216);
    expect(q.total).toBe(10000 - 1000 + 0 + 216);
  });

  it("taxes the volume-discounted price", () => {
    // 100 * 100 = 10000 gross, 15% off = 8500 -> CA 7.25% = 616.25 -> 616
    const q = buildQuote([line(100, 100)], "US-CA");
    expect(q.tax).toBe(616);
  });

  it("charges no tax for a zero-priced cart", () => {
    const q = buildQuote([line(0)], "EU-DE");
    expect(q.subtotal).toBe(0);
    expect(q.tax).toBe(0);
  });
});

describe("shipping", () => {
  it("charges flat shipping below the free-shipping threshold", () => {
    const q = buildQuote([line(FREE_SHIPPING_THRESHOLD - 1)], "US-OR");
    expect(q.shipping).toBe(FLAT_SHIPPING);
  });

  it("is free at exactly the threshold", () => {
    const q = buildQuote([line(FREE_SHIPPING_THRESHOLD)], "US-OR");
    expect(q.shipping).toBe(0);
  });

  it("evaluates the threshold before the coupon discount", () => {
    const q = buildQuote([line(FREE_SHIPPING_THRESHOLD)], "US-OR", { code: "HALF", kind: "percent", percent: 50 });
    expect(q.shipping).toBe(0);
  });

  it("evaluates the threshold after volume discounts", () => {
    // gross 7500, 5% volume discount -> 7125 < threshold
    const q = buildQuote([line(750, 10)], "US-OR");
    expect(q.subtotal).toBe(7125);
    expect(q.shipping).toBe(FLAT_SHIPPING);
  });

  it("total includes shipping, tax and coupon", () => {
    const q = buildQuote([line(5000)], "US-CA", { code: "FIVE", kind: "fixed", amount: 500 });
    // taxable 4500 * 7.25% = 326.25 -> 326
    expect(q.tax).toBe(326);
    expect(q.total).toBe(5000 - 500 + FLAT_SHIPPING + 326);
  });
});

describe("validation", () => {
  it("rejects an empty cart", () => {
    expect(() => buildQuote([], "US-CA")).toThrow(QuoteError);
  });

  it.each([0, -1, 1.5, NaN])("rejects quantity %s", (quantity) => {
    expect(() => buildQuote([line(100, quantity)], "US-CA")).toThrow(QuoteError);
  });

  it("rejects a negative price", () => {
    expect(() => buildQuote([line(-1)], "US-CA")).toThrow(QuoteError);
  });
});

import { type Cents, roundCents } from "../lib/money";

export type Region = "US-CA" | "US-NY" | "US-OR" | "EU-DE" | "EU-FR";

export type QuoteLine = { sku: string; unitPrice: Cents; quantity: number; taxExempt?: boolean };

export type Coupon =
  | { code: string; kind: "percent"; percent: number; minSubtotal?: Cents }
  | { code: string; kind: "fixed"; amount: Cents; minSubtotal?: Cents }
  | { code: string; kind: "free-shipping" };

export type Quote = {
  lines: { sku: string; quantity: number; unitPrice: Cents; lineTotal: Cents; volumeDiscount: Cents }[];
  subtotal: Cents;
  couponDiscount: Cents;
  shipping: Cents;
  tax: Cents;
  total: Cents;
  appliedCoupon: string | null;
};

export const TAX_RATES: Record<Region, number> = {
  "US-CA": 0.0725,
  "US-NY": 0.04,
  "US-OR": 0,
  "EU-DE": 0.19,
  "EU-FR": 0.2,
};

/** Per-line volume discount: 10+ units 5% off, 50+ units 10% off, 100+ units 15% off. */
export function volumeDiscountRate(quantity: number): number {
  if (quantity >= 100) return 0.15;
  if (quantity >= 50) return 0.1;
  if (quantity >= 10) return 0.05;
  return 0;
}

export const FREE_SHIPPING_THRESHOLD: Cents = 7500;
export const FLAT_SHIPPING: Cents = 695;

export class QuoteError extends Error {}

export function buildQuote(lines: QuoteLine[], region: Region, coupon?: Coupon): Quote {
  if (lines.length === 0) throw new QuoteError("cart is empty");
  for (const line of lines) {
    if (!Number.isInteger(line.quantity) || line.quantity <= 0) throw new QuoteError(`invalid quantity for ${line.sku}`);
    if (line.unitPrice < 0) throw new QuoteError(`invalid price for ${line.sku}`);
  }

  const priced = lines.map((line) => {
    const gross = line.unitPrice * line.quantity;
    const volumeDiscount = roundCents(gross * volumeDiscountRate(line.quantity));
    return { ...line, lineTotal: gross - volumeDiscount, volumeDiscount };
  });
  const subtotal = priced.reduce((sum, l) => sum + l.lineTotal, 0);

  let couponDiscount = 0;
  let appliedCoupon: string | null = null;
  let freeShipping = subtotal >= FREE_SHIPPING_THRESHOLD;
  if (coupon) {
    const min = "minSubtotal" in coupon ? (coupon.minSubtotal ?? 0) : 0;
    if (subtotal >= min) {
      appliedCoupon = coupon.code;
      if (coupon.kind === "percent") couponDiscount = roundCents(subtotal * (coupon.percent / 100));
      else if (coupon.kind === "fixed") couponDiscount = Math.min(coupon.amount, subtotal);
      else freeShipping = true;
    }
  }

  // The coupon discount is spread over taxable lines in proportion to their totals.
  const taxable = priced.filter((l) => !l.taxExempt).reduce((sum, l) => sum + l.lineTotal, 0);
  const taxableAfterCoupon = subtotal === 0 ? 0 : taxable - roundCents(couponDiscount * (taxable / subtotal));
  const tax = roundCents(taxableAfterCoupon * TAX_RATES[region]);
  const shipping = freeShipping ? 0 : FLAT_SHIPPING;

  return {
    lines: priced.map(({ sku, quantity, unitPrice, lineTotal, volumeDiscount }) => ({ sku, quantity, unitPrice, lineTotal, volumeDiscount })),
    subtotal,
    couponDiscount,
    shipping,
    tax,
    total: subtotal - couponDiscount + shipping + tax,
    appliedCoupon,
  };
}

/** Client for the Postbox transactional email API. */
export class Mailer {
  constructor(
    private apiKey: string,
    private baseUrl = "https://api.postbox.example",
    private fetchImpl: typeof fetch = fetch,
  ) {}

  async send(to: string, template: string, data: Record<string, unknown>): Promise<void> {
    const res = await this.fetchImpl(`${this.baseUrl}/messages`, {
      method: "POST",
      headers: { Authorization: `Bearer ${this.apiKey}`, "Content-Type": "application/json" },
      body: JSON.stringify({ to, template, data }),
    });
    if (!res.ok) throw new Error(`email failed with HTTP ${res.status}`);
  }
}

import { type Cents, formatMoney } from "../lib/money";

export type InvoiceLine = { description: string; quantity: number; unitPrice: Cents };

export type Invoice = {
  number: string;
  issuedOn: string; // YYYY-MM-DD
  dueInDays: number;
  seller: { name: string; address: string[]; vatId?: string };
  buyer: { name: string; address: string[]; email: string };
  lines: InvoiceLine[];
  taxRate: number; // e.g. 0.2 for 20%
  currency: string;
  notes?: string;
  paid?: boolean;
};

const escape = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

export function dueDate(issuedOn: string, dueInDays: number): string {
  const d = new Date(`${issuedOn}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + dueInDays);
  return d.toISOString().slice(0, 10);
}

export function invoiceTotals(invoice: Invoice) {
  const subtotal = invoice.lines.reduce((sum, l) => sum + l.unitPrice * l.quantity, 0);
  const tax = Math.round(subtotal * invoice.taxRate);
  return { subtotal, tax, total: subtotal + tax };
}

/** Renders the invoice as a standalone HTML document. */
export function renderInvoice(invoice: Invoice): string {
  if (invoice.lines.length === 0) throw new Error("invoice has no lines");
  const money = (c: Cents) => formatMoney(c, invoice.currency);
  const { subtotal, tax, total } = invoiceTotals(invoice);
  const address = (lines: string[]) => lines.map((l) => `<div>${escape(l)}</div>`).join("");
  const rows = invoice.lines
    .map(
      (l) =>
        `<tr><td>${escape(l.description)}</td><td class="num">${l.quantity}</td><td class="num">${money(l.unitPrice)}</td><td class="num">${money(l.unitPrice * l.quantity)}</td></tr>`,
    )
    .join("\n      ");
  return `<!doctype html>
<html>
<head><meta charset="utf-8"><title>Invoice ${escape(invoice.number)}</title></head>
<body>
  <header>
    <h1>Invoice ${escape(invoice.number)}</h1>
    ${invoice.paid ? '<p class="stamp">PAID</p>' : `<p class="due">Due ${dueDate(invoice.issuedOn, invoice.dueInDays)}</p>`}
  </header>
  <section class="parties">
    <div class="seller"><strong>${escape(invoice.seller.name)}</strong>${address(invoice.seller.address)}${invoice.seller.vatId ? `<div>VAT ${escape(invoice.seller.vatId)}</div>` : ""}</div>
    <div class="buyer"><strong>${escape(invoice.buyer.name)}</strong>${address(invoice.buyer.address)}<div>${escape(invoice.buyer.email)}</div></div>
  </section>
  <table>
    <thead><tr><th>Item</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead>
    <tbody>
      ${rows}
    </tbody>
    <tfoot>
      <tr><td colspan="3">Subtotal</td><td class="num">${money(subtotal)}</td></tr>
      <tr><td colspan="3">Tax (${(invoice.taxRate * 100).toFixed(1)}%)</td><td class="num">${money(tax)}</td></tr>
      <tr class="total"><td colspan="3">Total</td><td class="num">${money(total)}</td></tr>
    </tfoot>
  </table>
  ${invoice.notes ? `<footer><p>${escape(invoice.notes)}</p></footer>` : ""}
</body>
</html>
`;
}

