START = datetime(2026, 1, 1, 12, 0, tzinfo=UTC)


class FakePayments:
    def __init__(self):
        self.charges = []
        self.refunds = []
        self.charge_error = None
        self.refund_error = None
        self.decline_code = None

    def charge(self, token, amount, idempotency_key):
        self.charges.append((token, amount, idempotency_key))
        if self.charge_error:
            raise self.charge_error
        if self.decline_code:
            return Charge("ch_x", "declined", amount, self.decline_code)
        return Charge(f"ch_{len(self.charges)}", "succeeded", amount)

    def refund(self, charge_id):
        if self.refund_error:
            raise self.refund_error
        self.refunds.append(charge_id)


class FakeMailer:
    def __init__(self):
        self.sent = []
        self.error = None

    def send(self, to, template, data):
        if self.error:
            raise self.error
        self.sent.append((to, template, data))


class Clock:
    def __init__(self):
        self.current = START

    def __call__(self):
        return self.current

    def advance(self, delta):
