            service.cancel_order("ord_999")

    def test_cancel_at_exactly_24_hours_is_allowed(self, service, clock, payments):
        order = service.place_order(make_request())
        clock.advance(CANCEL_WINDOW)

        assert service.cancel_order(order.id).status == "cancelled"
        assert payments.refunds == [order.charge_id]

    def test_cancel_after_24_hours_is_rejected(self, service, clock, inventory, payments):
        order = service.place_order(make_request())
        clock.advance(CANCEL_WINDOW + timedelta(seconds=1))

        with pytest.raises(CancellationWindowClosed):
