        clock.advance(timedelta(days=30))  # window check must not apply to already-cancelled orders

        again = service.cancel_order(order.id)

        assert again.status == "cancelled"
        assert payments.refunds == [order.charge_id]
        assert inventory.available("widget") == 5

    def test_refund_failure_leaves_order_untouched(self, service, inventory, payments):
        order = service.place_order(make_request())
        payments.refund_error = PaymentError("refund failed with HTTP 500")

        with pytest.raises(PaymentError):
