  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json", ...headers } });

function setup(responses: Response[], maxRetries?: number) {
  const fetchImpl = vi.fn<typeof fetch>();
  for (const r of responses) fetchImpl.mockResolvedValueOnce(r);
  const sleep = vi.fn(async (_ms: number) => {});
  const client = new CarrierClient("key-123", { baseUrl: "https://test.local/v2", fetchImpl, sleep, maxRetries });
  return { client, fetchImpl, sleep };
}

const ratesBody = {
  shipment_id: "shp_1",
  rates: [
    { service_code: "exp", service_name: "Express", amount_cents: 2500, currency: "USD", estimated_days: 1 },
    { service_code: "std", service_name: "Standard", amount_cents: 900, currency: "USD", estimated_days: null },
  ],
};

describe("CarrierClient.getRates", () => {
  it("maps the request to snake_case and sends auth headers", async () => {
    const { client, fetchImpl } = setup([json(ratesBody)]);
