describe("CarrierClient retries", () => {
  const ok = () => json({ ...ratesBody });

  it("retries on 429 then succeeds", async () => {
    const { client, fetchImpl, sleep } = setup([json({}, 429), ok()]);
    await expect(client.getRates(from, to, parcel)).resolves.toHaveLength(2);
    expect(fetchImpl).toHaveBeenCalledTimes(2);
    expect(sleep).toHaveBeenCalledTimes(1);
  });

  it("retries on 5xx with exponential backoff", async () => {
    const { client, fetchImpl, sleep } = setup([json({}, 500), json({}, 503), ok()]);
    await client.getRates(from, to, parcel);
    expect(fetchImpl).toHaveBeenCalledTimes(3);
    expect(sleep.mock.calls.map((c) => c[0])).toEqual([500, 1000]);
  });

  it("honors the Retry-After header", async () => {
    const { client, sleep } = setup([json({}, 429, { "Retry-After": "3" }), ok()]);
    await client.getRates(from, to, parcel);
    expect(sleep).toHaveBeenCalledWith(3000);
  });

  it("gives up after maxRetries and throws the last error", async () => {
    const { client, fetchImpl } = setup([
      json({}, 502),
      json({}, 502),
      json({ error: { code: "unavailable", message: "try later" } }, 503),
    ]);
    await expect(client.getRates(from, to, parcel)).rejects.toMatchObject({ status: 503, code: "unavailable", message: "try later" });
    expect(fetchImpl).toHaveBeenCalledTimes(3); // 1 attempt + 2 retries
  });

  it("respects a custom maxRetries", async () => {
    const { client, fetchImpl } = setup([json({}, 500)], 0);
    await expect(client.getRates(from, to, parcel)).rejects.toBeInstanceOf(CarrierError);
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it("does not retry other 4xx errors", async () => {
    const { client, fetchImpl, sleep } = setup([json({ error: { code: "bad_request", message: "bad" } }, 400)]);
    await expect(client.getRates(from, to, parcel)).rejects.toMatchObject({ status: 400 });
    expect(fetchImpl).toHaveBeenCalledTimes(1);
    expect(sleep).not.toHaveBeenCalled();
  });
});

