import { type Cents, formatMoney } from "../lib/money";

export type InvoiceLine = { description: string; quantity: number; unitPrice: Cents };

export type Invoice = {
  number: string;
  issuedOn: string; // YYYY-MM-DD
  dueInDays: number;
  seller: { name: string; address: string[]; vatId?: string };
  buyer: { name: string; address: string[]; email: string };
  lines: InvoiceLine[];
  taxRate: number; // e.g. 0.2 for 20%
  currency: string;
  notes?: string;
  paid?: boolean;
};

const escape = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

export function dueDate(issuedOn: string, dueInDays: number): string {
  const d = new Date(`${issuedOn}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + dueInDays);
  return d.toISOString().slice(0, 10);
}

export function invoiceTotals(invoice: Invoice) {
  const subtotal = invoice.lines.reduce((sum, l) => sum + l.unitPrice * l.quantity, 0);
  const tax = Math.round(subtotal * invoice.taxRate);
  return { subtotal, tax, total: subtotal + tax };
}

/** Renders the invoice as a standalone HTML document. */
export function renderInvoice(invoice: Invoice): string {
  if (invoice.lines.length === 0) throw new Error("invoice has no lines");
  const money = (c: Cents) => formatMoney(c, invoice.currency);
  const { subtotal, tax, total } = invoiceTotals(invoice);
  const address = (lines: string[]) => lines.map((l) => `<div>${escape(l)}</div>`).join("");
  const rows = invoice.lines
    .map(
      (l) =>
        `<tr><td>${escape(l.description)}</td><td class="num">${l.quantity}</td><td class="num">${money(l.unitPrice)}</td><td class="num">${money(l.unitPrice * l.quantity)}</td></tr>`,
    )
    .join("\n      ");
  return `<!doctype html>
<html>
<head><meta charset="utf-8"><title>Invoice ${escape(invoice.number)}</title></head>
<body>
  <header>
    <h1>Invoice ${escape(invoice.number)}</h1>
    ${invoice.paid ? '<p class="stamp">PAID</p>' : `<p class="due">Due ${dueDate(invoice.issuedOn, invoice.dueInDays)}</p>`}
  </header>
  <section class="parties">
    <div class="seller"><strong>${escape(invoice.seller.name)}</strong>${address(invoice.seller.address)}${invoice.seller.vatId ? `<div>VAT ${escape(invoice.seller.vatId)}</div>` : ""}</div>
    <div class="buyer"><strong>${escape(invoice.buyer.name)}</strong>${address(invoice.buyer.address)}<div>${escape(invoice.buyer.email)}</div></div>
  </section>
  <table>
    <thead><tr><th>Item</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead>
    <tbody>
      ${rows}
    </tbody>
    <tfoot>
      <tr><td colspan="3">Subtotal</td><td class="num">${money(subtotal)}</td></tr>
      <tr><td colspan="3">Tax (${(invoice.taxRate * 100).toFixed(1)}%)</td><td class="num">${money(tax)}</td></tr>
      <tr class="total"><td colspan="3">Total</td><td class="num">${money(total)}</td></tr>
    </tfoot>
  </table>
  ${invoice.notes ? `<footer><p>${escape(invoice.notes)}</p></footer>` : ""}
</body>
</html>
`;
}

import type { ApiError, ApiRatesResponse, ApiTrackingResponse } from "./carrier-api";

export type Address = { line1: string; city: string; postalCode: string; country: string };
export type Parcel = { weightGrams: number; lengthCm: number; widthCm: number; heightCm: number };

export type Rate = { service: string; name: string; amountCents: number; currency: string; estimatedDays: number | null };
export type Tracking = { trackingNumber: string; status: string; delivered: boolean; lastLocation: string | null; history: { at: Date; status: string; message: string }[] };

export class CarrierError extends Error {
  constructor(message: string, readonly status: number, readonly code?: string) {
    super(message);
  }
}

/** Client for the ShipFast carrier API v2. */
export class CarrierClient {
  constructor(
    private apiKey: string,
    private options: { baseUrl?: string; fetchImpl?: typeof fetch; maxRetries?: number; sleep?: (ms: number) => Promise<void> } = {},
  ) {}

  private get baseUrl() {
    return this.options.baseUrl ?? "https://api.shipfast.example/v2";
  }

  private async request<T>(path: string, init: RequestInit = {}): Promise<T | null> {
    const fetchImpl = this.options.fetchImpl ?? fetch;
    const sleep = this.options.sleep ?? ((ms) => new Promise((r) => setTimeout(r, ms)));
    const maxRetries = this.options.maxRetries ?? 2;
    for (let attempt = 0; ; attempt++) {
      const res = await fetchImpl(`${this.baseUrl}${path}`, {
        ...init,
        headers: { Authorization: `Bearer ${this.apiKey}`, Accept: "application/json", ...(init.body ? { "Content-Type": "application/json" } : {}) },
      });
      if (res.status === 404) return null;
      if ((res.status === 429 || res.status >= 500) && attempt < maxRetries) {
        const retryAfter = Number(res.headers.get("Retry-After"));
        await sleep(Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : 500 * 2 ** attempt);
        continue;
      }
      if (!res.ok) {
        let code: string | undefined;
        let message = `ShipFast request failed with HTTP ${res.status}`;
        try {
          const body = (await res.json()) as ApiError;
          code = body.error.code;
          message = body.error.message;
        } catch {
          // not JSON
        }
        throw new CarrierError(message, res.status, code);
      }
      return (await res.json()) as T;
    }
  }

  /** Quotes for a parcel, cheapest first. */
  async getRates(from: Address, to: Address, parcel: Parcel): Promise<Rate[]> {
    if (parcel.weightGrams <= 0) throw new Error("parcel weight must be positive");
    const body = await this.request<ApiRatesResponse>("/rates", {
      method: "POST",
      body: JSON.stringify({
        from: { line1: from.line1, city: from.city, postal_code: from.postalCode, country: from.country },
        to: { line1: to.line1, city: to.city, postal_code: to.postalCode, country: to.country },
        parcel: { weight_g: parcel.weightGrams, length_cm: parcel.lengthCm, width_cm: parcel.widthCm, height_cm: parcel.heightCm },
      }),
    });
    if (!body) throw new CarrierError("rates endpoint not found", 404);
    return body.rates
      .map((r) => ({ service: r.service_code, name: r.service_name, amountCents: r.amount_cents, currency: r.currency, estimatedDays: r.estimated_days }))
      .sort((a, b) => a.amountCents - b.amountCents);
  }

  /** Tracking for a parcel, or null when ShipFast does not know the number. */
  async track(trackingNumber: string): Promise<Tracking | null> {
    const body = await this.request<ApiTrackingResponse>(`/tracking/${encodeURIComponent(trackingNumber)}`);
    if (!body) return null;
    const history = body.events
      .map((e) => ({ at: new Date(e.occurred_at), status: e.status, message: e.message, location: e.location }))
      .sort((a, b) => a.at.getTime() - b.at.getTime());
    const last = history.at(-1);
    return {
      trackingNumber: body.tracking_number,
      status: last?.status ?? "unknown",
      delivered: last?.status === "delivered",
      lastLocation: [...history].reverse().find((e) => e.location)?.location ?? null,
      history: history.map(({ at, status, message }) => ({ at, status, message })),
    };
  }
}

import { describe, expect, it, vi } from "vitest";
import { CarrierClient, CarrierError, type Address, type Parcel } from "./carrier";
import type { ApiError, ApiRatesResponse, ApiTrackingResponse } from "./carrier-api";

const from: Address = { line1: "1 Main St", city: "Austin", postalCode: "78701", country: "US" };
const to: Address = { line1: "2 High St", city: "London", postalCode: "SW1A 1AA", country: "GB" };
const parcel: Parcel = { weightGrams: 500, lengthCm: 10, widthCm: 20, heightCm: 5 };

const json = (body: unknown, status = 200, headers: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json", ...headers } });

const apiError = (status: number, code: string, message: string) => {
  const body: ApiError = { error: { code, message } };
  return json(body, status);
};
const ratesResponse = (body: ApiRatesResponse) => json(body);
const trackingResponse = (body: ApiTrackingResponse) => json(body);
const emptyRates: ApiRatesResponse = { shipment_id: "s", rates: [] };

function setup(responses: Response[], options: { maxRetries?: number } = {}) {
  const fetchImpl = vi.fn<typeof fetch>();
  for (const r of responses) fetchImpl.mockResolvedValueOnce(r);
  const sleep = vi.fn<(ms: number) => Promise<void>>().mockResolvedValue(undefined);
  const client = new CarrierClient("secret-key", { baseUrl: "https://test.invalid/v2", fetchImpl, sleep, ...options });
  return { client, fetchImpl, sleep };
}

describe("CarrierClient.getRates", () => {
  const ratesBody: ApiRatesResponse = {
    shipment_id: "shp_1",
    rates: [
      { service_code: "express", service_name: "Express", amount_cents: 2500, currency: "USD", estimated_days: 1 },
      { service_code: "ground", service_name: "Ground", amount_cents: 900, currency: "USD", estimated_days: null },
      { service_code: "air", service_name: "Air", amount_cents: 1500, currency: "USD", estimated_days: 3 },
    ],
  };

  it("maps rates to camelCase and sorts cheapest first", async () => {
    const { client } = setup([ratesResponse(ratesBody)]);
    const rates = await client.getRates(from, to, parcel);
    expect(rates).toEqual([
      { service: "ground", name: "Ground", amountCents: 900, currency: "USD", estimatedDays: null },
      { service: "air", name: "Air", amountCents: 1500, currency: "USD", estimatedDays: 3 },
      { service: "express", name: "Express", amountCents: 2500, currency: "USD", estimatedDays: 1 },
    ]);
  });

  it("POSTs a snake_case body with auth headers", async () => {
    const { client, fetchImpl } = setup([ratesResponse(ratesBody)]);
    await client.getRates(from, to, parcel);

    const [url, init] = fetchImpl.mock.calls[0];
    expect(url).toBe("https://test.invalid/v2/rates");
    expect(init?.method).toBe("POST");
    expect(init?.headers).toMatchObject({ Authorization: "Bearer secret-key", "Content-Type": "application/json" });
    expect(JSON.parse(init?.body as string)).toEqual({
      from: { line1: "1 Main St", city: "Austin", postal_code: "78701", country: "US" },
      to: { line1: "2 High St", city: "London", postal_code: "SW1A 1AA", country: "GB" },
      parcel: { weight_g: 500, length_cm: 10, width_cm: 20, height_cm: 5 },
    });
  });

  it("returns an empty list when there are no rates", async () => {
    const { client } = setup([ratesResponse({ shipment_id: "shp_2", rates: [] })]);
    expect(await client.getRates(from, to, parcel)).toEqual([]);
  });

  it.each([0, -1])("rejects non-positive weight (%d) without calling the API", async (weightGrams) => {
    const { client, fetchImpl } = setup([]);
    await expect(client.getRates(from, to, { ...parcel, weightGrams })).rejects.toThrow("parcel weight must be positive");
    expect(fetchImpl).not.toHaveBeenCalled();
  });

  it("throws a 404 CarrierError when the endpoint is not found", async () => {
    const { client } = setup([new Response(null, { status: 404 })]);
    await expect(client.getRates(from, to, parcel)).rejects.toMatchObject({ name: "Error", status: 404, message: "rates endpoint not found" });
  });
});

describe("CarrierClient.track", () => {
  const trackingBody: ApiTrackingResponse = {
