describe("retries", () => {
  it("retries on 429 then succeeds", async () => {
    const { client, fetchImpl, sleep } = setup([apiError(429, "rate_limited", "slow down"), ratesResponse(emptyRates)]);
    await expect(client.getRates(from, to, parcel)).resolves.toEqual([]);
    expect(fetchImpl).toHaveBeenCalledTimes(2);
    expect(sleep).toHaveBeenCalledTimes(1);
  });

  it("retries on 5xx with exponential backoff", async () => {
    const { client, fetchImpl, sleep } = setup([new Response(null, { status: 503 }), new Response(null, { status: 500 }), ratesResponse(emptyRates)]);
    await client.getRates(from, to, parcel);
    expect(fetchImpl).toHaveBeenCalledTimes(3);
    expect(sleep.mock.calls.map(([ms]) => ms)).toEqual([500, 1000]);
  });

  it("honours the Retry-After header (seconds)", async () => {
    const { client, sleep } = setup([new Response(null, { status: 429, headers: { "Retry-After": "3" } }), ratesResponse(emptyRates)]);
    await client.getRates(from, to, parcel);
    expect(sleep).toHaveBeenCalledWith(3000);
  });

  it("falls back to backoff when Retry-After is not numeric", async () => {
    const { client, sleep } = setup([new Response(null, { status: 429, headers: { "Retry-After": "soon" } }), ratesResponse(emptyRates)]);
    await client.getRates(from, to, parcel);
    expect(sleep).toHaveBeenCalledWith(500);
  });

  it("gives up after maxRetries and throws the last error", async () => {
    const { client, fetchImpl, sleep } = setup([
      apiError(503, "unavailable", "down 1"),
      apiError(503, "unavailable", "down 2"),
      apiError(503, "unavailable", "down 3"),
    ]);
    await expect(client.track("SF123")).rejects.toMatchObject({ status: 503, code: "unavailable", message: "down 3" });
    expect(fetchImpl).toHaveBeenCalledTimes(3); // 1 try + default 2 retries
    expect(sleep).toHaveBeenCalledTimes(2);
  });

  it("respects a custom maxRetries, including 0", async () => {
    const { client, fetchImpl, sleep } = setup([apiError(500, "boom", "boom")], { maxRetries: 0 });
    await expect(client.track("SF123")).rejects.toBeInstanceOf(CarrierError);
    expect(fetchImpl).toHaveBeenCalledTimes(1);
    expect(sleep).not.toHaveBeenCalled();
  });

  it("does not retry other 4xx errors", async () => {
    const { client, fetchImpl, sleep } = setup([apiError(400, "bad_request", "nope")]);
    await expect(client.getRates(from, to, parcel)).rejects.toMatchObject({ status: 400 });
    expect(fetchImpl).toHaveBeenCalledTimes(1);
    expect(sleep).not.toHaveBeenCalled();
  });
});

describe("API errors", () => {
  it("surfaces the API error code and message", async () => {
    const { client } = setup([apiError(401, "invalid_api_key", "API key is invalid")]);
    const err = await client.track("SF123").catch((e) => e);
    expect(err).toBeInstanceOf(CarrierError);
    expect(err).toMatchObject({ status: 401, code: "invalid_api_key", message: "API key is invalid" });
  });

  it("falls back to a generic message when the error body is not JSON", async () => {
    const { client } = setup([new Response("<html>Bad gateway</html>", { status: 502 })], { maxRetries: 0 });
    const err = await client.track("SF123").catch((e) => e);
    expect(err).toBeInstanceOf(CarrierError);
    expect(err).toMatchObject({ status: 502, code: undefined, message: "ShipFast request failed with HTTP 502" });
  });

  it("falls back to a generic message when the JSON has no error object", async () => {
    const { client } = setup([json({ unexpected: true }, 422)]);
    await expect(client.track("SF123")).rejects.toMatchObject({ status: 422, code: undefined, message: "ShipFast request failed with HTTP 422" });
  });

  it("propagates network failures", async () => {
    const fetchImpl = vi.fn<typeof fetch>().mockRejectedValue(new TypeError("fetch failed"));
    const client = new CarrierClient("k", { fetchImpl, sleep: async () => {} });
    await expect(client.track("SF123")).rejects.toThrow("fetch failed");
  });
});

