        clock.advance(hours=24, seconds=1)

        with pytest.raises(CancellationWindowClosed):
            service.cancel_order(order.id)

        assert payments.refunds == []
        assert inventory.available("widget") == 3
        assert service.get(order.id).status == "paid"

    def test_cancel_is_idempotent(self, service, payments, inventory, clock):
        order = service.place_order(make_request())
        service.cancel_order(order.id)
        clock.advance(days=30)  # already cancelled: window no longer matters

        again = service.cancel_order(order.id)

        assert again.status == "cancelled"
        assert payments.refunds == ["ch_1"]
        assert inventory.available("widget") == 5

    def test_refund_failure_keeps_order_paid(self, service, payments, inventory):
        order = service.place_order(make_request())
        payments.refund_error = PaymentError("refund failed with HTTP 500")

        with pytest.raises(PaymentError):
            service.cancel_order(order.id)

        assert service.get(order.id).status == "paid"
        assert inventory.available("widget") == 3

